### 3. Data Layer - Room Database (`app/src/main/java/com/example/todoapp/TaskDatabase.kt`)
This file contains the Entity, DAO, and Database instantiation.

```kotlin
package com.example.todoapp

import android.content.Context
import androidx.room.*
import kotlinx.coroutines.flow.Flow

// 1. Entity
@Entity(tableName = "tasks")
data class Task(
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    val title: String,
    val description: String,
    val dueTime: Long, // Stored as Timestamp
    val isCompleted: Boolean = false
)

// 2. DAO (Data Access Object) - Defines CRUD operations
@Dao
interface TaskDao {
    @Query("SELECT * FROM tasks ORDER BY isCompleted ASC, dueTime ASC")
    fun getAllTasks(): Flow<List<Task>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertTask(task: Task): Long

    @Update
    suspend fun updateTask(task: Task)

    @Delete
    suspend fun deleteTask(task: Task)

    @Query("SELECT * FROM tasks WHERE id = :taskId")
    suspend fun getTaskById(taskId: Int): Task?
}

// 3. Database
@Database(entities = [Task::class], version = 1, exportSchema = false)
abstract class TaskDatabase : RoomDatabase() {
    abstract fun taskDao(): TaskDao

    companion object {
        @Volatile
        private var INSTANCE: TaskDatabase? = null

        fun getDatabase(context: Context): TaskDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    TaskDatabase::class.java,
                    "task_database"
                ).build()
                INSTANCE = instance
                instance
            }
        }
    }
}
```

### 4. Reminder System (`app/src/main/java/com/example/todoapp/ReminderReceiver.kt`)
Handles broadcasting the notification when the alarm triggers.

```kotlin
package com.example.todoapp

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat

class ReminderReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val taskId = intent.getIntExtra("taskId", -1)
        val title = intent.getStringExtra("title") ?: "Task Reminder"

        createNotificationChannel(context)

        val notification = NotificationCompat.Builder(context, "task_reminder_channel")
            .setSmallIcon(android.R.drawable.ic_dialog_info)
            .setContentTitle("To-Do Reminder")
            .setContentText(title)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setAutoCancel(true)
            .build()

        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.notify(taskId, notification)
    }

    private fun createNotificationChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val name = "Task Reminders"
            val descriptionText = "Reminders for your to-do tasks"
            val channel = NotificationChannel("task_reminder_channel", name, NotificationManager.IMPORTANCE_HIGH).apply {
                description = descriptionText
            }
            val notificationManager = context.getSystemService(Context.NOTIFICATION_MANAGER) as NotificationManager
            notificationManager.createNotificationChannel(channel)
        }
    }
}
```

### 5. Application Class & Alarm Scheduler (`app/src/main/java/com/example/todoapp/TodoApp.kt`)
Initializes the database globally and contains the logic to schedule exact alarms.

```kotlin
package com.example.todoapp

import android.app.AlarmManager
import android.app.Application
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.content.getSystemService

class TodoApp : Application() {
    val database: TaskDatabase by lazy { TaskDatabase.getDatabase(this) }
}

object ReminderScheduler {
    fun scheduleReminder(context: Context, task: Task) {
        val alarmManager = context.getSystemService<AlarmManager>() ?: return

        // Android 12+ (S) requires permission check for exact alarms
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && !alarmManager.canScheduleExactAlarms()) {
            // In a production app, you'd prompt the user to go to settings.
            // For your project, just ensure the permission is in the manifest.
            return
        }

        val intent = Intent(context, ReminderReceiver::class.java).apply {
            putExtra("taskId", task.id)
            putExtra("title", task.title)
        }

        val pendingIntent = PendingIntent.getBroadcast(
            context,
            task.id,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        alarmManager.setExactAndAllowWhileIdle(
            AlarmManager.RTC_WAKEUP,
            task.dueTime,
            pendingIntent
        )
    }

    fun cancelReminder(context: Context, taskId: Int) {
        val alarmManager = context.getSystemService<AlarmManager>() ?: return
        val intent = Intent(context, ReminderReceiver::class.java)
        val pendingIntent = PendingIntent.getBroadcast(
            context,
            taskId,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        alarmManager.cancel(pendingIntent)
    }
}
```

### 6. ViewModel (`app/src/main/java/com/example/todoapp/TaskViewModel.kt`)
The bridge between the UI and the Database. Handles state management.

```kotlin
package com.example.todoapp

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class TaskViewModel(app: Application) : AndroidViewModel(app) {
    private val dao = (app as TodoApp).database.taskDao()

    // Exposes database flow as StateFlow for Compose to observe
    val tasks: StateFlow<List<Task>> = dao.getAllTasks()
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    fun addTask(title: String, description: String, dueTime: Long) {
        viewModelScope.launch {
            val newTask = Task(title = title, description = description, dueTime = dueTime)
            val id = dao.insertTask(newTask)
            val savedTask = newTask.copy(id = id.toInt())
            ReminderScheduler.scheduleReminder(getApplication(), savedTask)
        }
    }

    fun updateTask(task: Task) {
        viewModelScope.launch {
            dao.updateTask(task)
            ReminderScheduler.scheduleReminder(getApplication(), task) // Reschedule
        }
    }

    fun deleteTask(task: Task) {
        viewModelScope.launch {
            dao.deleteTask(task)
            ReminderScheduler.cancelReminder(getApplication(), task.id)
        }
    }

    fun toggleCompletion(task: Task) {
        viewModelScope.launch {
            dao.updateTask(task.copy(isCompleted = !task.isCompleted))
        }
    }
}
```

